-- Global Bank window: server tabs, the character list grouped by account (search, sort) and the chosen
-- character's bag or bank, laid out slot by slot so a search lights up where things are.
-- Frames are in GlobalBank.xml (generated by tools/gen_globalbank_xml.py).

local GB = GlobalBank

GB.ROWS = 20         -- list rows shown now (GB.ApplySize sets it from the window height)
GB.COLS, GB.GRID_ROWS = 10, 8
GB.MAX_ROWS, GB.MAX_GRID_ROWS = 48, 30 -- rows the XML declares (tools/gen_globalbank_xml.py)
GB.MAX_SERVER_TABS = 10
GB.tab = "bag"
GB.listOffset = 0
GB.gridOffset = 0 -- in rows
GB.serverStart = 1 -- first server tab shown, when there are more than fit
GB.rows, GB.servers, GB.serverInfo, GB.cells = {}, {}, {}, {}
GB.cellCount = 0
GB.cellsFor = nil

local function setShown(obj, on)
  if obj then
    if on then
      obj:Show()
    else
      obj:Hide()
    end
  end
end

local function shownNow()
  return GlobalBankFrame and GlobalBankFrame:IsVisible()
end

function GB.Toggle()
  if not GlobalBankFrame then
    GB.Print("|cffff6060the Global Bank window didn't load.|r Type /gb probe and send the result.")
    return
  end
  if GlobalBankFrame:IsVisible() then
    GlobalBankFrame:Hide()
    return
  end
  GlobalBankFrame:Show()
  if not GlobalBankFrame:IsVisible() then
    GB.Print("|cffff6060the window was told to open but isn't showing.|r Type /gb probe and send the result.")
  end
end

-- The window's OnShow; errors go to chat instead of leaving an empty window.
function GB.SafeShow()
  local ok, err = pcall(GB.OnShow)
  if not ok then
    GB.lastError = tostring(err)
    GB.Print("|cffff6060error while opening:|r " .. GB.lastError)
  end
end

function GB.OnShow()
  if GB.dirty or not GB.chars[GB.PlayerName() or ""] then
    GB.Snapshot(GB.bankOpen, GB.bankOpen)
  end
  if not GB.selected then
    GB.selected = GB.PlayerName()
  end
  -- The background helper updates the file whenever a character logs out, so read it on every open.
  GB.LoadDatabase()
  GB.ApplySavedSize() -- another character may have resized the window since
  GB.helperState = GB.HelperState()
  GB.WarnHelper(GB.helperState)
  GB.Redraw()
end

function GB.Changed()
  if shownNow() then
    GB.Redraw()
  end
end

function GB.OnSearchChanged(text)
  GB.listOffset = 0
  GB.gridOffset = 0
  GB.cellsFor = nil
  GB.SetSearch(text)
end

function GB.SetTab(tab)
  GB.tab = tab
  GB.gridOffset = 0
  GB.cellsFor = nil
  GB.Draw()
end

function GB.ToggleGroups()
  GB.groupBy = GB.groupBy == "account" and "none" or "account"
  GB.listOffset = 0
  GB.Redraw()
end

-- The server tabs: "" (every server) and then each server.
local function tabServers()
  local list = { "" }
  for _, server in ipairs(GB.servers) do
    list[#list + 1] = server
  end
  return list
end

function GB.ServerTabAt(i)
  return tabServers()[GB.serverStart + i - 1]
end

function GB.OnServerTab(i)
  local server = GB.ServerTabAt(i)
  if server == nil or server == GB.server then
    return
  end
  GB.server = server
  GB.listOffset = 0
  GB.Redraw()
  -- Show someone from that server straight away.
  local c = GB.selected and GB.chars[GB.selected]
  if server ~= "" and not (c and GB.ServerOf(c) == server) then
    local me = GB.PlayerName()
    local mine = me and GB.chars[me]
    GB.selected = (mine and GB.ServerOf(mine) == server) and me or GB.order[1]
    GB.gridOffset, GB.cellsFor = 0, nil
    GB.Draw()
  end
end

function GB.NextServerPage()
  GB.serverStart = GB.serverStart + (GB.serverShown or 1)
  if GB.serverStart > #tabServers() then
    GB.serverStart = 1
  end
  GB.Draw()
end

function GB.OnRowClick(i, key)
  local entry = GB.rows[GB.listOffset + i]
  if type(entry) == "table" then
    -- An account heading folds its characters away (not while searching: then it always shows them)
    if GB.search == "" then
      GB.collapsed[entry.id] = not GB.collapsed[entry.id] or nil
      GB.Redraw()
    end
    return
  end
  local name = entry
  if not name then
    return
  end
  if key == "RBUTTON" then
    GB.OpenMenu(name, _G["GlobalBankRow" .. i])
    return
  end
  GB.CloseMenu()
  GB.selected = name
  GB.gridOffset = 0
  GB.cellsFor = nil
  GB.Draw()
end

---------------------------------------------------------------------------
-- Right-click menu: Copy name, Remove entry from Global Bank
---------------------------------------------------------------------------

local function call(obj, method, ...)
  if obj and obj[method] then
    return pcall(obj[method], obj, ...)
  end
end

function GB.OpenMenu(name, row)
  if not GlobalBankMenu then
    return
  end
  GB.NoteCancel()
  GB.menuName, GB.menuConfirm = name, false
  GB.menuRow = row
  GlobalBankMenuName:SetText((GB.chars[name] and GB.chars[name].name) or name)
  GlobalBankMenuRemove:SetText("Remove entry from Global Bank")
  if GlobalBankMenuNote then
    GlobalBankMenuNote:SetText(GB.Note(name) ~= "" and "Edit note" or "Add note")
  end
  if row then
    call(GlobalBankMenu, "ClearAllAnchors")
    call(GlobalBankMenu, "SetAnchor", "TOPLEFT", "TOPRIGHT", row, 4, 0)
  end
  GlobalBankMenu:Show()
end

function GB.CloseMenu()
  GB.menuName, GB.menuConfirm = nil, false
  if GlobalBankMenu then
    call(GlobalBankMenuName, "ClearFocus")
    GlobalBankMenu:Hide()
  end
end

-- The name box only exists to be selected and copied; typing in it puts the name back.
function GB.MenuGuard()
  local c = GB.menuName and GB.chars[GB.menuName]
  local shown = c and c.name or GB.menuName
  if shown and GlobalBankMenuName:GetText() ~= shown then
    GlobalBankMenuName:SetText(shown)
  end
end

-- RoM's Chat_CopyToClipboard is undocumented, so the name is also selected in the box for Ctrl+C.
function GB.MenuCopy()
  local c = GB.menuName and GB.chars[GB.menuName]
  local name = c and c.name or GB.menuName -- the name alone, without a " (Server)" after it
  if not name then
    return
  end
  call(GlobalBankMenuName, "SetFocus")
  call(GlobalBankMenuName, "HighlightText")
  if type(Chat_CopyToClipboard) == "function" and pcall(Chat_CopyToClipboard, name) then
    GB.Print("copied " .. name .. ". If Ctrl+V pastes nothing, press Ctrl+C now: the name is selected.")
  else
    GB.Print("press Ctrl+C to copy " .. name .. " (it's selected in the box).")
  end
end

function GB.MenuNote()
  local name, row = GB.menuName, GB.menuRow
  if not name then
    return
  end
  GB.CloseMenu()
  GB.OpenNote(name, row)
end

---------------------------------------------------------------------------
-- Note editor
---------------------------------------------------------------------------

function GB.OpenNote(name, row)
  if not GlobalBankNoteEdit then
    return
  end
  GB.noteName = name
  GlobalBankNoteEditTitle:SetText("Note for " .. name .. " (empty clears it)")
  GlobalBankNoteEditBox:SetText(GB.Note(name))
  if row then
    call(GlobalBankNoteEdit, "ClearAllAnchors")
    call(GlobalBankNoteEdit, "SetAnchor", "TOPLEFT", "TOPRIGHT", row, 4, 0)
  end
  GlobalBankNoteEdit:Show()
  call(GlobalBankNoteEditBox, "SetFocus")
  call(GlobalBankNoteEditBox, "HighlightText")
end

function GB.NoteSave()
  local name = GB.noteName
  if name and GlobalBankNoteEditBox then
    GB.SetNote(name, GlobalBankNoteEditBox:GetText())
  end
  GB.NoteCancel()
end

function GB.NoteCancel()
  GB.noteName = nil
  if GlobalBankNoteEdit then
    call(GlobalBankNoteEditBox, "ClearFocus")
    GlobalBankNoteEdit:Hide()
  end
end

-- First click asks, second click removes.
function GB.MenuRemove()
  local name = GB.menuName
  if not name then
    return
  end
  local c = GB.chars[name]
  if c and c.live then
    GB.Print("you're playing " .. name .. " right now, so it can't be removed.")
    return
  end
  if not GB.menuConfirm then
    GB.menuConfirm = true
    GlobalBankMenuRemove:SetText("Click again to remove " .. name)
    return
  end
  GB.CloseMenu()
  GB.Remove(name)
end

-- Scroll bars and the mouse wheel. Setting a bar's value calls OnValueChanged, so redraws guard it.
-- Scrolling only draws again: the list itself is rebuilt when the data, search, sort or tab change.
local drawing = false

local function setBar(bar, max, value)
  if not bar then
    return
  end
  if max <= 0 then
    bar:Hide()
    return
  end
  if bar.SetMaxValue then
    bar:SetMaxValue(max) -- as Ultimate Mail Mod's scroll bars do
  elseif bar.SetMinMaxValues then
    bar:SetMinMaxValues(0, max)
  end
  bar:SetValue(value)
  bar:Show()
end

local function limits()
  local listMax = math.max(0, #GB.rows - GB.ROWS)
  local gridMax = math.max(0, math.ceil(GB.cellCount / GB.COLS) - GB.GRID_ROWS)
  return listMax, gridMax
end

function GB.OnScroll(which, value)
  if drawing then
    return
  end
  value = math.floor((tonumber(value) or 0) + 0.5)
  if which == "list" then
    GB.listOffset = value
  else
    GB.gridOffset = value
  end
  GB.Draw()
end

function GB.OnWheel(which, delta)
  local step = (tonumber(delta) or 0) > 0 and -1 or 1
  if which == "list" then
    GB.listOffset = GB.listOffset + step * 3
  else
    GB.gridOffset = GB.gridOffset + step
  end
  GB.Draw()
end

---------------------------------------------------------------------------
-- The chosen character's bag or bank, slot by slot: GB.cells[slot] = item, so an item is drawn where it
-- is kept. Rebuilt only when the character, tab, search or data change.
---------------------------------------------------------------------------

local GREEN, GREY, GOLD, RED, ORANGE = "|cff60ff60", "|cffa0a0a0", "|cffffd100", "|cffff6060", "|cffffa040"

local cellsTab, cellsList, cellsSearch = nil, nil, nil

local function tabList(c, tab)
  if not c then
    return nil
  end
  return (tab == "bank" and c.bank) or (tab == "bag" and c.bag) or nil
end

local function countMatches(list)
  local n = 0
  if GB.search ~= "" then
    for _, it in ipairs(list or {}) do
      if GB.ItemMatches(it) then
        n = n + 1
      end
    end
  end
  return n
end

function GB.BuildCells()
  local c = GB.selected and GB.chars[GB.selected]
  local list = tabList(c, GB.tab)
  if GB.cellsFor == c and cellsTab == GB.tab and cellsList == list and cellsSearch == GB.search then
    return
  end
  GB.cellsFor, cellsTab, cellsList, cellsSearch = c, GB.tab, list, GB.search
  local cells, lit, last, matches, first, spill = {}, {}, 0, 0, nil, {}
  for _, it in ipairs(list or {}) do
    local slot = tonumber(it.slot) or 0
    if slot >= 1 and not cells[slot] then
      cells[slot] = it
      last = math.max(last, slot)
    else
      spill[#spill + 1] = it
    end
  end
  for _, it in ipairs(spill) do -- an odd slot number still shows, after the rest
    last = last + 1
    cells[last] = it
  end
  local size = 0
  if c then
    size = GB.tab == "bank" and math.min(tonumber(c.bankMax) or 0, GB.BANK_SLOTS) or math.min(tonumber(c.bagMax) or 0, GB.BAG_SLOTS)
  end
  size = math.max(size, last)
  size = math.ceil(size / GB.COLS) * GB.COLS
  if GB.search ~= "" then
    for slot = 1, size do
      local it = cells[slot]
      if it and GB.ItemMatches(it) then
        lit[slot] = true
        matches = matches + 1
        first = first or slot
      end
    end
  end
  GB.cells, GB.cellLit, GB.cellCount, GB.cellMatches = cells, lit, size, matches
  if first then
    GB.gridOffset = math.floor((first - 1) / GB.COLS) -- scroll to the first match
  end
end

-- The item in grid cell i as drawn now.
function GB.CellItem(i)
  return GB.cells[GB.gridOffset * GB.COLS + i]
end

---------------------------------------------------------------------------
-- Drawing
---------------------------------------------------------------------------

local LIST_X, TABS_Y = 16, 68

local function drawServerTabs()
  local list = { "" }
  for _, server in ipairs(GB.servers) do
    list[#list + 1] = server
  end
  if GB.serverStart > #list then
    GB.serverStart = 1
  end
  local f = GlobalBankFrame
  local x, right = LIST_X, (GB.width or GB.DEFAULT_W) - 16 - 34
  local shown, full = 0, false
  for i = 1, GB.MAX_SERVER_TABS do
    local b = _G["GlobalBankFrameServer" .. i]
    local server = list[GB.serverStart + i - 1]
    local show = false
    if b and server and not full then
      local info = GB.serverInfo[server] or { n = 0, found = 0 }
      local label = (server == "" and "All servers" or server) .. " (" .. (GB.search ~= "" and info.found or info.n) .. ")"
      local w = math.max(60, math.min(190, 20 + 7 * string.len(label)))
      if shown > 0 and x + w > right then
        full = true
      else
        show = true
        b:SetText((server == GB.server and GOLD or "") .. label)
        call(b, "SetSize", w, 20)
        call(b, "ClearAllAnchors")
        call(b, "SetAnchor", "TOPLEFT", "TOPLEFT", f, x, TABS_Y)
        x = x + w + 2
        shown = i
      end
    end
    setShown(b, show)
  end
  GB.serverShown = math.max(shown, 1)
  local more = GlobalBankFrameServerMore
  local hidden = GB.serverStart > 1 or GB.serverStart + shown - 1 < #list
  if more and hidden then
    call(more, "ClearAllAnchors")
    call(more, "SetAnchor", "TOPLEFT", "TOPLEFT", f, x, TABS_Y)
  end
  setShown(more, hidden)
end

local function drawList()
  local rows = GB.rows
  local grouped = GB.groupBy == "account"
  local allServers = GB.server == ""
  for i = GB.ROWS + 1, GB.MAX_ROWS do
    setShown(_G["GlobalBankRow" .. i], false)
  end
  for i = 1, GB.ROWS do
    local rowName = "GlobalBankRow" .. i
    local row = _G[rowName]
    local entry = rows[GB.listOffset + i]
    if row then
      setShown(row, entry ~= nil)
      local group, note = _G[rowName .. "Group"], _G[rowName .. "Note"]
      if type(entry) == "table" then
        local fold = GB.search ~= "" and "" or (GB.collapsed[entry.id] and "[+] " or "[-] ")
        local label = fold .. entry.label .. (allServers and (" - " .. entry.server) or "") .. " (" .. entry.n .. ")"
        if group then
          group:SetText(GOLD .. label .. "|r")
        end
        _G[rowName .. "Name"]:SetText("")
        _G[rowName .. "Level"]:SetText("")
        _G[rowName .. "Gold"]:SetText("")
        _G[rowName .. "Items"]:SetText(GB.search ~= "" and (GOLD .. entry.found .. "|r") or tostring(entry.items))
        if note then
          note:SetText(GREY .. GB.FormatGold(entry.gold) .. " gold|r")
        end
        setShown(_G[rowName .. "Head"], true)
        setShown(_G[rowName .. "Back"], false)
      elseif entry then
        local c = GB.chars[entry]
        local shownName = allServers and entry or c.name
        if group then
          group:SetText("")
        end
        _G[rowName .. "Name"]:SetText((grouped and "  " or "") .. (c.live and GREEN or "") .. shownName)
        _G[rowName .. "Level"]:SetText((c.lvl or 0) > 0 and tostring(c.lvl) or "")
        _G[rowName .. "Gold"]:SetText(GB.FormatGold(c.money))
        if GB.search ~= "" and (GB.found[entry] or 0) > 0 then
          _G[rowName .. "Items"]:SetText(GOLD .. GB.found[entry] .. "|r")
        else
          _G[rowName .. "Items"]:SetText(GB.Filled(c) .. (c.bank and "" or "*"))
        end
        if note then
          note:SetText(GB.Note(entry))
        end
        setShown(_G[rowName .. "Head"], false)
        setShown(_G[rowName .. "Back"], entry == GB.selected)
      end
    end
  end
end

local function drawDetail()
  local c = GB.selected and GB.chars[GB.selected]
  if not c then
    GlobalBankFrameCharName:SetText(#GB.order > 0 and "Click a character" or "")
    GlobalBankFrameCharInfo:SetText("")
    GlobalBankFrameCharGold:SetText("")
    GlobalBankFrameGridNote:SetText("")
    GlobalBankFrameTabBag:SetText("Bag")
    GlobalBankFrameTabBank:SetText("Bank")
    for i = 1, GB.COLS * GB.MAX_GRID_ROWS do
      setShown(_G["GlobalBankItem" .. i], false)
    end
    return
  end
  GlobalBankFrameCharName:SetText(c.name .. (c.live and (GREEN .. "  (playing now)|r") or ""))
  local info = {}
  if c.lvl and c.lvl > 0 then
    info[#info + 1] = "Level " .. c.lvl
  end
  if c.cls and c.cls ~= "" then
    info[#info + 1] = c.cls
  end
  info[#info + 1] = GB.ServerOf(c)
  local when = c.when ~= "" and c.when or c.saved
  if when and when ~= "" then
    info[#info + 1] = "snapshot " .. when
  end
  GlobalBankFrameCharInfo:SetText(table.concat(info, ", "))
  local note = GB.Note(GB.selected)
  local account = GB.accounts and GB.accounts[GB.selected]
  GlobalBankFrameCharGold:SetText(GB.FormatGold(c.money) .. " gold" .. (account and (GREY .. "   " .. account.label .. "|r") or "")
    .. (note ~= "" and ("   " .. GREY .. note .. "|r") or ""))
  local bagLabel, bankLabel = "Bag (" .. #c.bag .. ")", c.bank and ("Bank (" .. #c.bank .. ")") or "Bank (not seen)"
  if GB.search ~= "" then
    local inBag, inBank = countMatches(c.bag), countMatches(c.bank)
    bagLabel = "Bag (" .. (inBag > 0 and (GREEN .. inBag .. " found|r") or "0 found") .. ")"
    bankLabel = c.bank and ("Bank (" .. (inBank > 0 and (GREEN .. inBank .. " found|r") or "0 found") .. ")") or bankLabel
  end
  GlobalBankFrameTabBag:SetText((GB.tab == "bag" and GOLD or "") .. bagLabel)
  GlobalBankFrameTabBank:SetText((GB.tab == "bank" and GOLD or "") .. bankLabel)

  local searching = GB.search ~= ""
  local first = GB.gridOffset * GB.COLS
  for i = 1, GB.COLS * GB.MAX_GRID_ROWS do
    local cellName = "GlobalBankItem" .. i
    local slot = first + i
    local inView = i <= GB.COLS * GB.GRID_ROWS and slot <= GB.cellCount
    local it = inView and GB.cells[slot] or nil
    setShown(_G[cellName], inView)
    if inView then
      local icon = _G[cellName .. "Icon"]
      if it then
        icon:SetTexture(it.icon ~= "" and it.icon or "Interface\\Icons\\skill_war1-2")
        _G[cellName .. "Count"]:SetText(it.count > 1 and tostring(it.count) or "")
      else
        _G[cellName .. "Count"]:SetText("")
      end
      setShown(icon, it ~= nil)
      local lit = GB.cellLit[slot] == true
      setShown(_G[cellName .. "Glow"], lit)
      setShown(_G[cellName .. "Dim"], searching and it ~= nil and not lit)
    end
  end
  local text
  if GB.tab == "bank" and not c.bank then
    text = GREY .. "Bank not seen yet: open the bank once on " .. c.name .. "."
  elseif searching then
    text = GB.cellMatches .. " matching " .. (GB.cellMatches == 1 and "stack" or "stacks") .. " here, lit up"
  elseif GB.tab == "bank" then
    text = #c.bank .. " filled bank slots"
  else
    text = #c.bag .. " filled of " .. (c.bagMax > 0 and c.bagMax or "?") .. " bag slots"
  end
  GlobalBankFrameGridNote:SetText(text)
end

local function drawStatus()
  local here = GB.serverInfo[GB.server or ""] or { n = 0, gold = 0, found = 0 }
  local all = GB.serverInfo[""] or here
  local where = (GB.server == "" or GB.server == nil) and "All servers" or GB.server
  local status
  if GB.search ~= "" then
    status = where .. ": " .. here.found .. " of " .. here.n .. " characters match \"" .. GB.search .. "\""
    if all.found > here.found then
      status = status .. GOLD .. ", " .. (all.found - here.found) .. " more on other servers|r"
    end
  else
    status = where .. ": " .. here.n .. " characters, " .. GB.FormatGold(here.gold) .. " gold"
    if here ~= all then
      status = status .. GREY .. "   (all servers: " .. all.n .. " characters, " .. GB.FormatGold(all.gold) .. " gold)|r"
    end
  end
  GlobalBankFrameStatus:SetText(status)
  local run = "run \"Start Global Bank helper.bat\" in CherrysKit\\GlobalBank\\Helper and keep it open."
  if GB.helperState == "running" and GB.db.loaded then
    GlobalBankFrameHint:SetText(GREY .. "Helper running; other characters updated " .. tostring(GB.db.made or "?")
      .. ". * = bank not seen yet. Click an account to fold it.")
  elseif GB.helperState == "stopped" then
    GlobalBankFrameHint:SetText(ORANGE .. "Helper not running, other characters may be out of date: " .. run)
  elseif GB.helperState == "running" then
    GlobalBankFrameHint:SetText(GREY .. "Helper running; other characters appear once they log out.")
  else
    GlobalBankFrameHint:SetText(RED .. "Only this character is shown: " .. run)
  end
  local arrow = GB.sortDesc and " v" or " ^"
  GlobalBankFrameSortName:SetText("Name" .. (GB.sortBy == "name" and arrow or ""))
  GlobalBankFrameSortLevel:SetText("Level" .. (GB.sortBy == "level" and arrow or ""))
  GlobalBankFrameSortGold:SetText("Gold" .. (GB.sortBy == "gold" and arrow or ""))
  GlobalBankFrameSortItems:SetText("Items" .. (GB.sortBy == "items" and arrow or ""))
  if GlobalBankFrameSortNote then
    GlobalBankFrameSortNote:SetText("Note" .. (GB.sortBy == "note" and arrow or ""))
  end
  if GlobalBankFrameGroup then
    GlobalBankFrameGroup:SetText(GB.groupBy == "account" and (GOLD .. "Accounts") or "No groups")
  end
end

-- Draws what GB.BuildList last built: used on its own for scrolling, clicking a character or a tab.
function GB.Draw()
  if not GlobalBankFrame then
    return
  end
  GB.BuildCells()
  local listMax, gridMax = limits()
  GB.listOffset = math.max(0, math.min(GB.listOffset, listMax))
  GB.gridOffset = math.max(0, math.min(GB.gridOffset, gridMax))
  drawing = true
  setBar(GlobalBankFrameListScroll, listMax, GB.listOffset)
  setBar(GlobalBankFrameGridScroll, gridMax, GB.gridOffset)
  drawing = false
  drawServerTabs()
  drawList()
  drawDetail()
  drawStatus()
end

function GB.Redraw()
  if not GlobalBankFrame then
    return
  end
  GB.BuildList()
  if GB.search ~= "" then
    -- While searching, pick the first match so its items show straight away...
    if not GB.selected or not GB.found[GB.selected] or not GB.InTab(GB.selected) then
      GB.selected = GB.order[1]
      GB.cellsFor = nil
    end
    -- ...on the tab that has them.
    local c = GB.selected and GB.chars[GB.selected]
    if c and countMatches(tabList(c, GB.tab)) == 0 then
      local other = GB.tab == "bag" and "bank" or "bag"
      if countMatches(tabList(c, other)) > 0 then
        GB.tab = other
        GB.cellsFor = nil
      end
    end
  end
  GB.Draw()
end

-- True when key is in the list as it is now (its server's tab, or all servers).
function GB.InTab(key)
  local c = GB.chars[key]
  return c ~= nil and (GB.server == "" or GB.server == nil or GB.ServerOf(c) == GB.server)
end

---------------------------------------------------------------------------
-- Tooltips. The window is a DIALOG frame, so the game's tooltips (and the comparison tooltips it opens beside
-- an item) are lifted to the TOOLTIP layer before showing; otherwise they draw behind the window.
---------------------------------------------------------------------------

GB.TIP_FRAMES = { "GameTooltip", "GameTooltip1", "GameTooltip2", "ItemRefTooltip" }

function GB.TipsOnTop()
  for _, name in ipairs(GB.TIP_FRAMES) do
    local tip = _G[name]
    if tip and tip.SetFrameStrata then
      pcall(tip.SetFrameStrata, tip, "TOOLTIP")
    end
  end
end

function GB.HideTips()
  if GameTooltip then
    GameTooltip:Hide()
  end
  if GameTooltip1 then
    GameTooltip1:Hide()
  end
  if GameTooltip2 then
    GameTooltip2:Hide()
  end
end

GB.TIPS = {
  button = { "Global Bank", "Every character's bag, bank and gold. Search for an item to see who has it." },
  refresh = { "Refresh", "Reads this character again, and the other characters the helper has collected." },
  items = { "Sort by items", "Filled bag and bank slots." },
  note = { "Note", "A short note shown in the list, for example what this character holds or is for. Search finds notes too. It shows on all your characters after the helper's next update." },
  grip = { "Resize", "Drag to make the window bigger or smaller. /gb size reset puts it back." },
  remove = { "Remove entry", "Hides this character from Global Bank on all your characters (after the helper's next update). It comes back by itself when that character logs in again." },
  group = { "Accounts", "Groups characters by account: the ones the login screen lists together. Click an account to fold it. Click here for one plain list." },
  search = { "Search", "Finds items, character names and notes. Each server tab shows how many characters match, and the bag or bank lights up the matching slots." },
  servermore = { "More servers", "Shows the server tabs that don't fit." },
}

function GB.ShowTip(owner, what)
  local tip = GB.TIPS[what]
  if tip and GameTooltip then
    GB.TipsOnTop()
    GameTooltip:SetOwner(owner, "ANCHOR_RIGHT", 4, 0)
    GameTooltip:SetText(tip[1], 1, 1, 1)
    GameTooltip:AddLine(tip[2], 0, 0.75, 0.95)
    GameTooltip:Show()
  end
end

function GB.ShowServerTip(owner, i)
  local server = GB.ServerTabAt(i)
  local info = server and GB.serverInfo[server]
  if not info or not GameTooltip then
    return
  end
  GB.TipsOnTop()
  GameTooltip:SetOwner(owner, "ANCHOR_BOTTOM", 0, 0)
  GameTooltip:SetText(server == "" and "All servers" or server, 1, 1, 1)
  GameTooltip:AddLine(info.n .. " characters, " .. GB.FormatGold(info.gold) .. " gold", 1, 0.82, 0)
  if GB.search ~= "" then
    GameTooltip:AddLine(info.found .. " match \"" .. GB.search .. "\"", 0.4, 1, 0.4)
  end
  GameTooltip:Show()
end

function GB.TooltipLink(it)
  local kept = it.gear or it.stone
  if kept and kept.link and kept.link ~= "" then
    return "|Hitem:" .. kept.link .. "|h|h"
  end
  local id = tonumber(it.id)
  return id and string.format("|Hitem:%x|h|h", id) or nil
end

function GB.OnItemEnter(owner, i)
  local it = GB.CellItem(i)
  if not it or not GameTooltip then
    return
  end
  GB.TipsOnTop()
  GameTooltip:SetOwner(owner, "ANCHOR_RIGHT", 4, 0)
  -- The game's own tooltip. Gear keeps its link for its own durability and stats; the rest only needs an ID.
  local link = GB.TooltipLink(it)
  local shown = link and pcall(function() GameTooltip:SetHyperLink(link) end)
  local title = shown and GameTooltipTextLeft1 and GameTooltipTextLeft1:GetText()
  if not title or title == "" then
    GameTooltip:SetText(it.name, 1, 1, 1)
  end
  if it.count > 1 then
    GameTooltip:AddLine("Count: " .. it.count, 1, 0.82, 0)
  end
  GameTooltip:AddLine((GB.tab == "bank" and "Bank" or "Bag") .. " slot " .. it.slot, 0.6, 0.6, 0.6)
  GameTooltip:Show()
  GB.TipsOnTop() -- again, for comparison tooltips the game only made while showing this one
end

---------------------------------------------------------------------------
-- Window size: drag the corner grip (bottom right). The size is kept like a note (GB.SIZE_KEY), so
-- every character opens the window at the size it was last given.
-- RoM units (measured in game for Cherry's Chat): GetCursorPos and GetLeft/GetTop are screen pixels
-- with +y down, sizes are UI units, and screen pixels = UI units * GetUIScale().
---------------------------------------------------------------------------

GB.DEFAULT_W, GB.DEFAULT_H = 900, 580
GB.MIN_W, GB.MIN_H = 790, 500
GB.MAX_W, GB.MAX_H = 1600, 1100
GB.sizeErrors = {}

local LIST_X, TOP_Y, ROW_H, CELL, NOTE_X = 16, 108, 20, 36, 254
local GRID_Y = TOP_Y + 70

local function uiScale()
  local s = GetUIScale and GetUIScale()
  return (type(s) == "number" and s > 0) and s or 1
end

function GB.ClampSize(w, h)
  w = math.floor(tonumber(w) or GB.DEFAULT_W)
  h = math.floor(tonumber(h) or GB.DEFAULT_H)
  return math.max(GB.MIN_W, math.min(GB.MAX_W, w)), math.max(GB.MIN_H, math.min(GB.MAX_H, h))
end

local function safe(what, fn)
  local ok, err = pcall(fn)
  if not ok then
    GB.sizeErrors[what] = tostring(err)
  end
end

-- Lays the window out for w x h: the Note column takes the extra width, extra height adds list
-- rows and item rows.
function GB.ApplySize(w, h)
  w, h = GB.ClampSize(w, h)
  GB.width, GB.height = w, h
  GB.ROWS = math.max(1, math.min(GB.MAX_ROWS, math.floor((h - TOP_Y - 54) / ROW_H)))
  GB.GRID_ROWS = math.max(1, math.min(GB.MAX_GRID_ROWS, math.floor((h - GRID_Y - 72) / CELL)))
  local noteW = w - 704
  local f = GlobalBankFrame
  if not f then
    return w, h
  end
  safe("frame", function() f:SetSize(w, h) end)
  safe("rows", function()
    for i = 1, GB.MAX_ROWS do
      call(_G["GlobalBankRow" .. i], "SetSize", NOTE_X + noteW + 4, ROW_H)
      call(_G["GlobalBankRow" .. i .. "Note"], "SetSize", noteW, ROW_H)
    end
    call(GlobalBankFrameHeadNote, "SetSize", noteW, 14)
    call(GlobalBankFrameStatus, "SetSize", w - 52, 16)
    call(GlobalBankFrameHint, "SetSize", w - 52, 16)
  end)
  safe("scroll", function()
    local x = LIST_X + NOTE_X + noteW + 8
    call(GlobalBankFrameListScroll, "ClearAllAnchors")
    call(GlobalBankFrameListScroll, "SetAnchor", "TOPLEFT", "TOPLEFT", f, x, TOP_Y)
    call(GlobalBankFrameListScroll, "SetAnchor", "BOTTOMLEFT", "TOPLEFT", f, x, TOP_Y + GB.ROWS * ROW_H)
    call(GlobalBankFrameGridScroll, "ClearAllAnchors")
    call(GlobalBankFrameGridScroll, "SetAnchor", "TOPLEFT", "TOPRIGHT", f, -36, GRID_Y)
    call(GlobalBankFrameGridScroll, "SetAnchor", "BOTTOMLEFT", "TOPRIGHT", f, -36, GRID_Y + GB.GRID_ROWS * CELL)
  end)
  if shownNow() then
    GB.Redraw()
  end
  return w, h
end

function GB.ApplySavedSize()
  local w, h = string.match(GB.Note(GB.SIZE_KEY), "^(%d+)x(%d+)$")
  if not GB.drag then
    GB.ApplySize(w or GB.DEFAULT_W, h or GB.DEFAULT_H)
  end
end

function GB.SaveSize()
  GB.SetNote(GB.SIZE_KEY, GB.width .. "x" .. GB.height, true)
end

function GB.ResetSize()
  GB.ApplySize(GB.DEFAULT_W, GB.DEFAULT_H)
  GB.SaveSize()
  GB.Print("window size reset to " .. GB.width .. " x " .. GB.height .. ".")
end

-- Pins the top-left corner where it is now, so dragging moves only the bottom-right corner (the
-- window starts anchored by its centre). Same as Advanced AuctionHouse's grip.
local function pinTopLeft()
  local f = GlobalBankFrame
  local ok1, left = call(f, "GetLeft")
  local ok2, top = call(f, "GetTop")
  if not (ok1 and ok2 and left and top) then
    return
  end
  local s = uiScale()
  call(f, "ClearAllAnchors")
  call(f, "SetAnchor", "TOPLEFT", "TOPLEFT", "UIParent", left / s, top / s)
  local _, left2 = call(f, "GetLeft")
  local _, top2 = call(f, "GetTop")
  -- If GetLeft turned out to be UI units rather than pixels, the window jumped: use them as they are.
  if left2 and top2 and (math.abs(left2 - left) > 3 or math.abs(top2 - top) > 3) then
    call(f, "ClearAllAnchors")
    call(f, "SetAnchor", "TOPLEFT", "TOPLEFT", "UIParent", left, top)
  end
end

function GB.GripDown()
  if not GetCursorPos then
    GB.Print("this game client can't follow the mouse; the window keeps its size.")
    return
  end
  local x, y = GetCursorPos()
  pinTopLeft()
  GB.drag = { x = x, y = y, w = GB.width or GB.DEFAULT_W, h = GB.height or GB.DEFAULT_H, scale = uiScale() }
end

function GB.GripUpdate()
  local d = GB.drag
  if not d or not GetCursorPos then
    return
  end
  local x, y = GetCursorPos()
  -- right makes it wider, down makes it taller
  local w, h = GB.ClampSize(d.w + (x - d.x) / d.scale, d.h + (y - d.y) / d.scale)
  if w ~= GB.width or h ~= GB.height then
    GB.ApplySize(w, h)
  end
end

function GB.GripUp()
  if GB.drag then
    GB.drag = nil
    GB.SaveSize()
  end
end
